import{_ as e,o as n,c as s,a2 as i}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第十五章 地役权","description":"","frontmatter":{"title":"第十五章 地役权","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/disanfenbian：yongyiwuquan（dishiwuzhang：diyiquan）.md","filePath":"blogs/CC/第三分编：用益物权（第十五章：地役权）.md"}'),r={name:"blogs/CC/disanfenbian：yongyiwuquan（dishiwuzhang：diyiquan）.md"};function l(t,a,p,o,h,d){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h3 id="第三百七十二条" tabindex="-1">第三百七十二条 <a class="header-anchor" href="#第三百七十二条" aria-label="Permalink to &quot;第三百七十二条&quot;">​</a></h3><p>地役权人有权按照合同约定，利用他人的不动产，以提高自己的不动产的效益。 前款所称他人的不动产为供役地，自己的不动产为需役地。</p><h3 id="第三百七十三条" tabindex="-1">第三百七十三条 <a class="header-anchor" href="#第三百七十三条" aria-label="Permalink to &quot;第三百七十三条&quot;">​</a></h3><p>设立地役权，当事人应当采用书面形式订立地役权合同。 地役权合同一般包括下列条款：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）当事人的姓名或者名称和住所；</span></span>
<span class="line"><span>（二）供役地和需役地的位置；</span></span>
<span class="line"><span>（三）利用目的和方法；</span></span>
<span class="line"><span>（四）地役权期限；</span></span>
<span class="line"><span>（五）费用及其支付方式；</span></span>
<span class="line"><span>（六）解决争议的方法。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="第三百七十四条" tabindex="-1">第三百七十四条 <a class="header-anchor" href="#第三百七十四条" aria-label="Permalink to &quot;第三百七十四条&quot;">​</a></h3><p>地役权自地役权合同生效时设立。当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。</p><h3 id="第三百七十五条" tabindex="-1">第三百七十五条 <a class="header-anchor" href="#第三百七十五条" aria-label="Permalink to &quot;第三百七十五条&quot;">​</a></h3><p>供役地权利人应当按照合同约定，允许地役权人利用其不动产，不得妨害地役权人行使权利。</p><h3 id="第三百七十六条" tabindex="-1">第三百七十六条 <a class="header-anchor" href="#第三百七十六条" aria-label="Permalink to &quot;第三百七十六条&quot;">​</a></h3><p>地役权人应当按照合同约定的利用目的和方法利用供役地，尽量减少对供役地权利人物权的限制。</p><h3 id="第三百七十七条" tabindex="-1">第三百七十七条 <a class="header-anchor" href="#第三百七十七条" aria-label="Permalink to &quot;第三百七十七条&quot;">​</a></h3><p>地役权期限由当事人约定；但是，不得超过土地承包经营权、建设用地使用权等用益物权的剩余期限。</p><h3 id="第三百七十八条" tabindex="-1">第三百七十八条 <a class="header-anchor" href="#第三百七十八条" aria-label="Permalink to &quot;第三百七十八条&quot;">​</a></h3><p>土地所有权人享有地役权或者负担地役权的，设立土地承包经营权、宅基地使用权等用益物权时，该用益物权人继续享有或者负担已经设立的地役权。</p><h3 id="第三百七十九条" tabindex="-1">第三百七十九条 <a class="header-anchor" href="#第三百七十九条" aria-label="Permalink to &quot;第三百七十九条&quot;">​</a></h3><p>土地上已经设立土地承包经营权、建设用地使用权、宅基地使用权等用益物权的，未经用益物权人同意，土地所有权人不得设立地役权。</p><h3 id="第三百八十条" tabindex="-1">第三百八十条 <a class="header-anchor" href="#第三百八十条" aria-label="Permalink to &quot;第三百八十条&quot;">​</a></h3><p>地役权不得单独转让。土地承包经营权、建设用地使用权等转让的，地役权一并转让，但是合同另有约定的除外。</p><h3 id="第三百八十一条" tabindex="-1">第三百八十一条 <a class="header-anchor" href="#第三百八十一条" aria-label="Permalink to &quot;第三百八十一条&quot;">​</a></h3><p>地役权不得单独抵押。土地经营权、建设用地使用权等抵押的，在实现抵押权时，地役权一并转让。</p><h3 id="第三百八十二条" tabindex="-1">第三百八十二条 <a class="header-anchor" href="#第三百八十二条" aria-label="Permalink to &quot;第三百八十二条&quot;">​</a></h3><p>需役地以及需役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，受让人同时享有地役权。</p><h3 id="第三百八十三条" tabindex="-1">第三百八十三条 <a class="header-anchor" href="#第三百八十三条" aria-label="Permalink to &quot;第三百八十三条&quot;">​</a></h3><p>供役地以及供役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，地役权对受让人具有法律约束力。</p><h3 id="第三百八十四条" tabindex="-1">第三百八十四条 <a class="header-anchor" href="#第三百八十四条" aria-label="Permalink to &quot;第三百八十四条&quot;">​</a></h3><p>地役权人有下列情形之一的，供役地权利人有权解除地役权合同，地役权消灭：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）违反法律规定或者合同约定，滥用地役权；</span></span>
<span class="line"><span>（二）有偿利用供役地，约定的付款期限届满后在合理期限内经两次催告未支付费用。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="第三百八十五条" tabindex="-1">第三百八十五条 <a class="header-anchor" href="#第三百八十五条" aria-label="Permalink to &quot;第三百八十五条&quot;">​</a></h3><p>已经登记的地役权变更、转让或者消灭的，应当及时办理变更登记或者注销登记。</p>`,30)])])}const b=e(r,[["render",l]]);export{u as __pageData,b as default};
